    except ValueError:
        return {}
220→    by_source_path = {str(Path(s["path"]).parent): s for s in registry["skills"]}
    out = {}
    for plugin in data.get("plugins", []):
        name = plugin.get("name")
        if not name:
            continue
        names = set()
        paths = plugin.get("skills")
        if isinstance(paths, list):
            for p in paths:
230→                skill = by_source_path.get(str(p).replace(pkg_prefix, "", 1))
                if skill:
                    names.add(skill["name"])
        else:
            source = str(plugin.get("source", ""))
            if source.startswith(pkg_prefix):
